37	Status VectorColumnIndexer::CreateProximaIndex(
38	    const vector_column_params::ReadOptions &read_options) {
39	  auto index_param_result =
40	      ProximaEngineHelper::convert_to_engine_index_param(field_schema_);
41	  if (!index_param_result.has_value()) {
42	    return Status::InvalidArgument(index_param_result.error().message());
43	  }
44	  auto &index_param = index_param_result.value();
