231	int MixedStreamerReducer::dump(const IndexDumper::Pointer &dumper) {
232	  LOG_INFO("Begin brute force reducer dump");
233	
234	  if (state_ != STATE_REDUCE) {
235	    LOG_WARN("Reduce first before dump");
236	    return IndexError_NoReady;
237	  }
238	
239	  ailego::ElapsedTime timer;
240	  int ret = 0;
241	  if (target_builder_ != nullptr) {
242	    target_builder_->dump(dumper);
243	  } else {
244	    target_streamer_->dump(dumper);
245	  }
246	  if (ret == IndexError_NotImplemented) {
247	    LOG_WARN("Dump index not implemented");
248	  } else if (ret < 0) {
249	    LOG_ERROR("Failed to dump in streamer");
250	  }
251	
252	  return ret;
253	}
254	
255	int MixedStreamerReducer::read_vec(size_t source_streamer_index,
256	                                   const IndexProvider::Pointer &provider,
257	                                   const IndexFilter &filter,
258	                                   const uint32_t id_offset,
259	                                   uint32_t *next_id) {
260	  const auto &streamer = streamers_[source_streamer_index];
261	  const auto &reformer = source_streamers_reformers_[source_streamer_index];
262	  const IndexQueryMeta source_streamer_query_meta{streamer->meta().data_type(),
263	                                                  streamer->meta().dimension()};
264	
265	  bool need_revert = (target_streamer_->meta().reformer_name() !=
266	                          streamer->meta().reformer_name() &&
267	                      reformer != nullptr);
268	  if (target_builder_ && reformer) {
269	    need_revert = true;
270	  }
271	
272	  if (!provider) {
273	    LOG_ERROR("Source provider is null, index=%zu", source_streamer_index);
274	    return IndexError_Runtime;
275	  }
276	  IndexProvider::Iterator::Pointer iterator = provider->create_iterator();
277	  if (!iterator) {
278	    LOG_ERROR("Failed to create source provider iterator, index=%zu",
279	              source_streamer_index);
280	    return IndexError_Runtime;
281	  }
282	
283	  while (iterator->is_valid()) {
284	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
285	      LOG_DEBUG("read_vec cancelled.");
286	      return 0;
287	    }
288	    if (filter(iterator->key() + (uint64_t)id_offset)) {
289	      (*stats_.mutable_filtered_count())++;
290	      iterator->next();
291	      continue;
292	    }
293	
294	    const void *vector_data = iterator->data();
295	    if (!vector_data) {
296	      LOG_ERROR("Failed to read source vector, index=%zu key=%zu",
297	                source_streamer_index, static_cast<size_t>(iterator->key()));
298	      return IndexError_ReadData;
299	    }
300	
301	    std::vector<uint8_t> bytes;
302	    if (need_revert) {
303	      std::string new_vector;
304	      if (reformer->revert(vector_data, source_streamer_query_meta,
305	                           &new_vector) != 0) {
306	        LOG_ERROR("Failed to revert the vector");
307	        return IndexError_Runtime;
308	      }
309	      bytes.resize(new_vector.size());
310	      memcpy(bytes.data(), new_vector.data(), bytes.size());
311	    } else {
312	      // TODO: eliminate the copy
313	      bytes.resize(provider->element_size());
314	      memcpy(bytes.data(), vector_data, bytes.size());
315	    }
316	
317	    // TODO: use id instead of key
318	    if (!mt_list_.produce(VectorItem((*next_id)++, std::move(bytes)))) {
319	      LOG_ERROR("Produce vector to queue failed. key[%lu]",
320	                (size_t)iterator->key());
321	      return IndexError_Runtime;
322	    }
323	    iterator->next();
324	  }
325	  return 0;
326	}
327	
328	void MixedStreamerReducer::add_vec(int *result) {
329	  if (target_builder_ != nullptr) {
330	    add_vec_with_builder(result);
331	    return;
332	  }
333	  ailego::ElapsedTime timer;
334	  auto target_streamer_context = target_streamer_->create_context();
335	  auto target_streamer_query_meta = IndexQueryMeta{
336	      IndexMeta::MetaType::MT_DENSE, target_streamer_->meta().data_type(),
337	      target_streamer_->meta().dimension()};
338	  const bool need_convert = (!is_target_and_source_same_reformer_) &&
339	                            target_streamer_reformer_ != nullptr;
340	
341	  AILEGO_DEFER([&]() {
342	    // make producer quit
343	    mt_list_.done();
344	  });
345	
346	  VectorItem vector_item;
347	  while (mt_list_.consume(&vector_item)) {
348	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
349	      LOG_DEBUG("add_vec cancelled.");
350	      return;
351	    }
352	
353	    const void *vector = vector_item.vec_.data();
354	    std::string new_vector;
355	
356	
357	    if (need_convert) {
358	      IndexQueryMeta new_meta;
359	      if (target_streamer_reformer_->convert(vector, original_query_meta_,
360	                                             &new_vector, &new_meta) != 0) {
361	        LOG_ERROR("Failed to transform vector");
362	        *result = IndexError_Runtime;
363	        return;
364	      }
365	      vector = new_vector.data();
366	    }
367	    // 1. no reformer: target_streamer_query_meta_ = original_query_meta_
368	    // 2. has reformer, matched(need_convert = false): use
369	    // target_streamer_query_meta_
370	    // 3. has reformer, not matched(need_convert = true): use
371	    // target_streamer_query_meta_
372	
373	
374	    // TODO: use id instead of key
375	    int ret = target_streamer_->add_with_id_impl(
376	        (uint32_t)vector_item.pkey_, vector, target_streamer_query_meta,
377	        target_streamer_context);
378	    if (ret != 0) {
379	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
380	                ret, IndexError::What(ret), (size_t)vector_item.pkey_);
381	      *result = ret;
382	      return;
383	    }
384	  }
385	
386	  *result = 0;
387	  LOG_DEBUG("add_vec. cost time: [%zu]s", (size_t)timer.seconds());
388	  return;
389	}
390	
391	void MixedStreamerReducer::add_vec_with_builder(int *result) {
392	  ailego::ElapsedTime timer;
393	
394	  AILEGO_DEFER([&]() {
395	    // make producer quit
396	    mt_list_.done();
397	  });
398	
399	  VectorItem vector_item;
400	  while (mt_list_.consume(&vector_item)) {
401	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
402	      LOG_DEBUG("add_vec cancelled.");
403	      return;
404	    }
405	
406	    const void *vector = vector_item.vec_.data();
407	    std::string out_vector_buffer = std::string(
408	        static_cast<const char *>(vector),
409	        original_query_meta_.dimension() * original_query_meta_.unit_size());
410	    PushToDocCache(original_query_meta_, (uint32_t)vector_item.pkey_,
411	                   out_vector_buffer);
412	  }
413	
414	  *result = 0;
415	  LOG_DEBUG("add_vec. cost time: [%zu]s", (size_t)timer.seconds());
416	  return;
417	}
418	
419	void MixedStreamerReducer::add_sparse_vec(int *result) {
420	  ailego::ElapsedTime timer;
421	  auto target_streamer_context = target_streamer_->create_context();
422	  auto target_streamer_query_meta = IndexQueryMeta{
423	      IndexMeta::MetaType::MT_SPARSE,
424	      target_streamer_->meta().data_type(),
425	  };
426	
427	  auto need_convert = !is_target_and_source_same_reformer_ &&
428	                      target_streamer_reformer_ != nullptr;
429	
430	  AILEGO_DEFER([&]() {
431	    // make producer quit
432	    sparse_mt_list_.done();
433	  });
434	
435	  SparseVectorItem sparse_vector_item;
436	  while (sparse_mt_list_.consume(&sparse_vector_item)) {
437	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
438	      LOG_DEBUG("add_sparse_vec cancelled.");
439	      return;
440	    }
441	    auto sparse_count = sparse_vector_item.sparse_indices_.size();
442	    auto indices = sparse_vector_item.sparse_indices_.data();
443	    auto values = sparse_vector_item.sparse_values_.data();
444	
445	    std::string converted_sparse_values_buffer;
446	    if (need_convert) {
447	      IndexQueryMeta new_meta;
448	      if (target_streamer_reformer_->convert(
449	              sparse_count, indices, values, original_query_meta_,
450	              &converted_sparse_values_buffer, &new_meta) != 0) {
451	        LOG_ERROR("Failed to transform vector");
452	        *result = IndexError_Runtime;
453	        return;
454	      }
455	      values = converted_sparse_values_buffer.data();
456	      target_streamer_query_meta = new_meta;
457	    }
458	
459	    // TODO: use id instead of key
460	    int ret = target_streamer_->add_with_id_impl(
461	        (uint32_t)sparse_vector_item.pkey_, sparse_count, indices, values,
462	        target_streamer_query_meta, target_streamer_context);
463	    if (ret != 0) {
464	      LOG_ERROR("Insert target streamer failed. ret[%d] reason[%s] pkey[%zu]",
465	                ret, IndexError::What(ret), (size_t)sparse_vector_item.pkey_);
466	      *result = ret;
467	      return;
468	    }
469	  }
470	
471	  *result = 0;
472	  LOG_DEBUG("add_sparse_vec. cost time: [%zu]s", (size_t)timer.seconds());
473	  return;
474	}
475	
476	
477	int MixedStreamerReducer::read_sparse_vec(size_t source_streamer_index,
478	                                          const IndexFilter &filter,
479	                                          const uint32_t id_offset,
480	                                          uint32_t *next_id) {
481	  const auto &streamer = streamers_[source_streamer_index];
482	  const auto &reformer = source_streamers_reformers_[source_streamer_index];
483	  const bool need_revert =
484	      !is_target_and_source_same_reformer_ && reformer != nullptr;
485	
486	  IndexStreamer::SparseProvider::Pointer provider =
487	      streamer->create_sparse_provider();
488	  IndexStreamer::SparseProvider::Iterator::Pointer iterator =
489	      provider->create_iterator();
490	
491	  while (iterator->is_valid()) {
492	    if (stop_flag_ != nullptr && stop_flag_->load(std::memory_order_relaxed)) {
493	      LOG_DEBUG("read_sparse_vec cancelled.");
494	      return 0;
495	    }
496	    if (filter(iterator->key() + (uint64_t)id_offset)) {
497	      (*stats_.mutable_filtered_count())++;
498	      iterator->next();
499	      continue;
500	    }
501	
502	    auto sparse_count = iterator->sparse_count();
503	    std::vector<uint32_t> sparse_indices(sparse_count);
504	    std::string sparse_values;
505	
506	    if (need_revert) {
507	      std::string new_sparse_values;
508	      if (reformer->revert(iterator->sparse_count(), iterator->sparse_indices(),
509	                           iterator->sparse_data(),
510	                           {
511	                               IndexMeta::MetaType::MT_SPARSE,
512	                               streamer->meta().data_type(),
513	                           },
514	                           &new_sparse_values) != 0) {
515	        LOG_ERROR("Failed to revert the sparse vector");
516	        return IndexError_Runtime;
517	      }
518	      sparse_values = std::move(new_sparse_values);
519	    } else {
520	      sparse_values.resize(sparse_count * streamer->meta().unit_size());
521	      memcpy(sparse_values.data(), iterator->sparse_data(),
522	             sparse_values.size());
523	    }
524	
525	    // TODO: eliminate the copy
526	    memcpy(sparse_indices.data(), iterator->sparse_indices(),
527	           sparse_indices.size() * sizeof(uint32_t));
528	
529	    // TODO: use id instead of key
530	    if (!sparse_mt_list_.produce(SparseVectorItem((*next_id)++,
531	                                                  std::move(sparse_indices),
532	                                                  std::move(sparse_values)))) {
533	      LOG_ERROR("Produce vector to queue failed. key[%lu]",
534	                (size_t)iterator->key());
535	      return IndexError_Runtime;
536	    }
537	    iterator->next();
538	  }
539	  return 0;
540	}
541	
542	void MixedStreamerReducer::PushToDocCache(const IndexQueryMeta &meta,
543	                                          uint32_t doc_id, std::string &doc) {
544	  std::lock_guard<std::mutex> lock(mutex_);
545	  while (doc_cache_.size() <= doc_id) {
546	    std::string fake_data(meta.dimension() * meta.unit_size(), 0);
547	    doc_cache_.push_back(std::make_pair(kInvalidKey, fake_data));
548	  }
549	  doc_cache_[doc_id] = std::make_pair(doc_id, doc);
550	}
551	
552	int MixedStreamerReducer::IndexBuild() {
553	  IndexHolder::Pointer target_holder;
554	  if (original_query_meta_.data_type() == core::IndexMeta::DataType::DT_FP16) {
555	    auto holder = std::make_shared<
556	        zvec::core::MultiPassIndexHolder<core::IndexMeta::DataType::DT_FP16>>(
557	        original_query_meta_.dimension());
558	    for (auto doc : doc_cache_) {
559	      ailego::NumericalVector<uint16_t> vec(doc.second);
560	      if (doc.first == kInvalidKey) {
561	        continue;
562	      }
563	      if (!holder->emplace(doc.first, vec)) {
564	        LOG_ERROR("Failed to add vector");
565	        return core::IndexError_Runtime;
566	      }
567	    }
568	    target_holder = holder;
569	  } else if (original_query_meta_.data_type() ==
570	             core::IndexMeta::DataType::DT_FP32) {
571	    auto holder = std::make_shared<
572	        zvec::core::MultiPassIndexHolder<core::IndexMeta::DataType::DT_FP32>>(
573	        original_query_meta_.dimension());
574	    for (auto doc : doc_cache_) {
575	      ailego::NumericalVector<float> vec(doc.second);
576	      if (doc.first == kInvalidKey) {
577	        continue;
578	      }
579	      if (!holder->emplace(doc.first, vec)) {
580	        LOG_ERROR("Failed to add vector");
581	        return core::IndexError_Runtime;
582	      }
583	    }
584	    target_holder = holder;
585	  } else if (original_query_meta_.data_type() ==
586	             core::IndexMeta::DataType::DT_INT8) {
587	    auto holder = std::make_shared<
588	        zvec::core::MultiPassIndexHolder<core::IndexMeta::DataType::DT_INT8>>(
589	        original_query_meta_.dimension());
590	    for (auto doc : doc_cache_) {
591	      ailego::NumericalVector<uint8_t> vec(doc.second);
592	      if (doc.first == kInvalidKey) {
593	        continue;
594	      }
595	      if (!holder->emplace(doc.first, vec)) {
596	        LOG_ERROR("Failed to add vector");
597	        return core::IndexError_Runtime;
598	      }
599	    }
600	    target_holder = holder;
601	  } else {
602	    LOG_ERROR("data_type is not support");
603	    return core::IndexError_Runtime;
604	  }
605	  if (target_builder_converter_) {
606	    core::IndexConverter::TrainAndTransform(target_builder_converter_,
607	                                            target_holder);
608	    target_holder = target_builder_converter_->result();
609	  }
610	  int ret = target_builder_->train(target_holder);
611	  if (ret != 0) {
612	    LOG_ERROR("Failed to train target builder, ret=%d", ret);
613	    return ret;
614	  }
615	  ret = target_builder_->build(target_holder);
616	  if (ret != 0) {
617	    LOG_ERROR("Failed to build target index, ret=%d", ret);
618	    return ret;
619	  }
620	  return 0;
621	}
622	
623	INDEX_FACTORY_REGISTER_STREAMER_REDUCER_ALIAS(MixedStreamerReducer,
624	                                              MixedStreamerReducer);
625	
