81	                           uint32_t topk) {
82	    // Finish turns accumulated block docs into the public result format:
83	    // rank all docs globally, keep topk, then split ResultDoc back into the
84	    // doc list and optional reverted payload lists expected by
85	    // VectorIndexResults.
86	    std::sort(docs_.begin(), docs_.end(),
87	              [metric_type](const ResultDoc &lhs, const ResultDoc &rhs) {
88	                return IsBetterScore(metric_type, lhs.doc.score(),
89	                                     rhs.doc.score());
