91	    if (docs_.size() > topk) {
92	      docs_.resize(topk);
93	    }
94	
95	    core::IndexDocumentList doc_list;
96	    std::vector<std::string> reverted_vector_list;
97	    std::vector<std::string> reverted_sparse_values_list;
98	    doc_list.reserve(docs_.size());
99	    reverted_vector_list.reserve(docs_.size());
100	    reverted_sparse_values_list.reserve(docs_.size());
101	
102	    for (auto &doc : docs_) {
103	      doc_list.emplace_back(std::move(doc.doc));
104	      reverted_vector_list.emplace_back(std::move(doc.reverted_vector));
105	      reverted_sparse_values_list.emplace_back(
106	          std::move(doc.reverted_sparse_values));
107	    }
108	    if (!HasRevertedValues(reverted_vector_list)) {
109	      reverted_vector_list.clear();
110	    }
111	    if (!HasRevertedValues(reverted_sparse_values_list)) {
112	      reverted_sparse_values_list.clear();
113	    }
114	
115	    return std::make_unique<VectorIndexResults>(
